<div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Printers</h2><p>Local LAN printers; no internet required</p></div></div><div class="panel-body"><div class="table-wrap"><table class="table" style="min-width:520px"><thead><tr><th>Name</th><th>Station</th><th>Address</th><th>Type</th></tr></thead><tbody><?php foreach($printers as $p):?><tr><td><b><?=e($p['name'])?></b></td><td><?=e($p['station_code'])?></td><td><?=e($p['ip_address'])?>:<?=e((string)$p['port_no'])?></td><td><?=e($p['printer_type'])?></td></tr><?php endforeach;?></tbody></table></div></div></section><section class="panel"><div class="panel-head"><div><h2>Pending Print Jobs</h2></div></div><div class="panel-body"><div class="table-wrap"><table class="table" style="min-width:520px"><thead><tr><th>Queued</th><th>Printer</th><th>Type</th><th>Status</th></tr></thead><tbody><?php foreach($jobs as $j):?><tr><td><?=e($j['queued_at'])?></td><td><?=e($j['printer_name'])?></td><td><?=e($j['job_type'])?></td><td><span class="tag orange"><?=e($j['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div></section></div><div class="panel" style="margin-top:10px"><div class="panel-head"><div><h2>Category Printer Routing</h2></div></div><div class="panel-body"><div class="table-wrap"><table class="table"><thead><tr><th>Category</th><th>Printer</th><th>Station</th><th>Rule</th></tr></thead><tbody><?php foreach($routes as $r):?><tr><td><b><?=e($r['category'])?></b></td><td><?=e($r['printer'])?></td><td><?=e($r['station_code'])?></td><td><?=e($r['print_rule'])?></td></tr><?php endforeach;?></tbody></table></div></div></div>
